CREATE FUNCTION pg_temp.check_t(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAILED: %',message; END IF; END $$;
CREATE FUNCTION pg_temp.reject_t(statement text,expected text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 EXECUTE statement;RAISE EXCEPTION 'Unexpected success: %',statement;
 EXCEPTION WHEN OTHERS THEN IF SQLSTATE<>expected THEN RAISE; END IF;END $$;
GRANT EXECUTE ON FUNCTION pg_temp.check_t(boolean,text),pg_temp.reject_t(text,text) TO anon,authenticated;
SELECT pg_temp.check_t(NOT EXISTS((SELECT row FROM trainer_services_before) EXCEPT SELECT to_jsonb(s) FROM public.services s),'Existing services preserved');
